  'features.cockpitDesc': 'Fügt die Seite „Cockpit“ (`/cockpit`) hinzu: Dashboards aus Widgets, die live aus GitLab und Jira lesen, jeweils mit deinem eigenen Token. Mitgeliefert sind Quellen für Merge Requests (von dir, Review von dir, dir zugewiesen, pro Projekt oder Gruppe), fehlgeschlagene CI-Jobs über alle Repositories und Jira-Abfragen in JQL. Jedes Widget hat Filter, Sortierung, Hervorhebungen und eine Ansicht als Liste, Tabelle, Zahl oder Board und kann bei neuen Treffern benachrichtigen. Widgets und ganze Dashboards gibst du als JSON an Kollegen weiter, Tokens sind nie enthalten. Platzhalter wie `{{var:repo}}` füllt jeder selbst. Dashboards sind versteckte Notizen und synchronisieren, die Daten werden nur live abgefragt und nicht gespeichert. Als Codeblock ```cockpit stehen Widgets auch in normalen Notizen und lesen dort die Eigenschaften der Notiz (`{{this.jira}}`). Beim Einschalten wird das Dashboard „Mein Tag“ angelegt. Dazu kommt die Seite „Prozesse“ (`/processes`): Modelle beschreiben Stufen, Schritte, Entscheidungen, Bedingungen und Sub-Workflows; ein Lauf führt ein Feature oder einen Bug hindurch, mit Ziel-Branch, betroffenen Repositories und vorgeschlagenem Branch. Prüfungen lesen live aus GitLab und Jira, der Lauf speichert nur Verweise. Zwei Beispiele (Wasserfall, Fehlerbehebung) werden angelegt.',
