  'features.calloutsTitle': 'Callouts',
  'features.calloutsDesc': 'Zitate, die mit `> [!typ] Titel` beginnen, erscheinen als farbige Box mit Symbol, z. B. `note`, `tip`, `warning`, `danger`, `question`, `example` oder `quote` (wie in Obsidian). Mit `-` nach dem Typ (`> [!note]- Titel`) ist die Box eingeklappt, mit `+` aufgeklappt; ein Klick auf den Pfeil öffnet und schließt sie. Neue Boxen fügst du mit `/callout` ein. Öffentliche Links, PDF und Word zeigen sie genauso. Ohne die Funktion bleiben es einfache Zitate.',
