  'features.presentationTitle': 'Präsentationen',
  'features.presentationDesc': 'Zeigt im Notizmenü „Präsentation starten“ und beim Export „Präsentation (PDF)“. Jedes `---` nach einer Leerzeile beginnt eine neue Folie (ohne Trennlinien jede `#`- und `##`-Überschrift); alles nach einer Zeile `Note:` sind Sprechernotizen. Das Folienformat wählst du an der Notiz (Frontmatter `presentation: 4:3`, sonst 16:9). Bilder, Diagramme, Tabellen und Einbettungen erscheinen wie in der Notiz. Ohne die Funktion bleibt `---` eine einfache Trennlinie.',
