  // MCP Settings
  'mcp.title': 'KI-Assistenten',
  'mcp.intro': 'Über das Model Context Protocol (MCP) sprechen KI-Assistenten wie Claude mit deinen Notizen: suchen, lesen, Aufgaben auflisten und – wenn du es erlaubst – Notizen anlegen und ergänzen. Jede Verbindung meldet sich mit deinem Konto an und sieht nur deine eigenen Notizen.',
  'mcp.connectTitle': 'Verbinden',
  'mcp.connectDesc': 'Trage diese Adresse in deinem Assistenten als MCP-Server bzw. Connector ein (z. B. claude.ai → Einstellungen → Connectors → „Benutzerdefinierten Connector hinzufügen“). Beim ersten Aufruf öffnet sich Kladde, du meldest dich an und bestätigst den Zugriff.',
