  // Import (CLI tokens)
  'import.title': 'Import',
  'import.intro': 'Mit der Import-CLI bringst du einen lokalen Ordner – etwa einen Obsidian-Vault – in deinen Space: Markdown- und Textdateien werden zu Notizen, verlinkte Bilder und PDFs zu Anhängen. Vorhandene Pfade werden übersprungen, nie überschrieben. Vor dem Import zeigt die CLI eine Vorschau und fragt nach.',
  'import.cliTitle': 'Aufruf',
  'import.cliDesc': 'Im Kladde-Repository nach „npm ci“ und „npm run build“ ausführen; das Token steht in der Umgebungsvariable KLADDE_IMPORT_TOKEN. Mit --dry-run nur die Vorschau zeigen.',
  'import.createTitle': 'Import-Token erstellen',
