  'settings.shortcutsTitle': 'Apple Kurzbefehle',
  'settings.shortcutsDesc': 'Teilen-Menü, Siri, Action-Taste und fällige Aufgaben auf iPhone und iPad',
  'shortcuts.title': 'Apple Kurzbefehle',
  'shortcuts.intro': 'Mit der Kurzbefehle-App erscheint Kladde im Teilen-Menü von iOS, lässt sich per Siri, Action-Taste, Doppeltippen auf die Rückseite oder Widget starten und kann dir jeden Morgen deine fälligen Aufgaben als Mitteilung zeigen – auch dort, wo die Web-App das nicht kann. Ein Kurzbefehl-Token erlaubt nur diese Aktionen, keinen Zugriff auf dein Konto.',
  'shortcuts.serverTitle': 'Server-Adresse',
  'shortcuts.serverDesc': 'Diese Adresse kommt in die Aktion „Inhalte von URL abrufen“, ergänzt um den Endpunkt (z. B. …/capture).',
  'shortcuts.insecureHint': 'Diese Seite läuft über http: Token und Notizen würden unverschlüsselt übertragen. Nutze Kurzbefehle nur über https.',
  'shortcuts.guideLink': 'Anleitung: Kurzbefehle einrichten',
  'shortcuts.createTitle': 'Token erstellen',
  'shortcuts.createDesc': 'Erstelle ein Token pro Gerät. Es ist standardmäßig ein Jahr gültig und kann jederzeit widerrufen werden.',
  'shortcuts.tokenNamePlaceholder': 'Name, z. B. „iPhone“',
  'shortcuts.headerHint': 'In Kurzbefehlen als Header „Authorization“ mit diesem Wert eintragen:',
