  'shortcuts.recipeNoteTitle': 'Schnelle Notiz',
  'shortcuts.recipeNoteDesc': 'Diktieren oder tippen: Der Text wird an die heutige Tagesnotiz angehängt (oder an eine Notiz per „path“).',
  'shortcuts.recipeTaskTitle': 'Neue Aufgabe',
  'shortcuts.recipeTaskDesc': 'Mit Datumsauswahl; landet bei den freien Aufgaben der Startseite oder in einer Notiz.',
  'shortcuts.recipeDueTitle': 'Heute fällig',
