  'webhooks.intro': "Ein Webhook pro GitLab-Projekt (oder Gruppe) bzw. GitHub-Repository genügt: Kladde prüft das Secret, übersetzt die Ereignisse (Merge Requests, Pushes, Pipelines, Kommentare, …) und gibt sie an die Ticket-Automationen und an alle Plugins weiter, die sie abonnieren.",
