  'calendar.title': 'Kalender-Feed',
  'calendar.intro': 'Ein Kalender-Feed zeigt deine offenen Aufgaben mit Fälligkeitsdatum in deiner Kalender-App – neben deinen Terminen. Wiederkehrende Aufgaben erscheinen als Serie, jeder Eintrag verlinkt auf seine Notiz. Der Feed ist nur lesbar; wer die Adresse kennt, sieht die Aufgaben, also gib sie nicht weiter.',
