  'features.cockpitDesc': "Adds the \"Cockpit\" page (`/cockpit`): dashboards of widgets that read GitLab and Jira live, each with your own token. It comes with sources for merge requests (by you, your reviews, assigned to you, per project or group), failed CI jobs across all repositories and Jira queries in JQL. Every widget has filters, a sort order, highlights and a view as list, table, count or board, and can notify you about new hits. You pass widgets and whole dashboards to colleagues as JSON; tokens are never part of it, and placeholders like `{{var:repo}}` are filled in by everyone themselves. Dashboards are hidden notes and sync; the data is only read live and never stored. As a ```cockpit code block, widgets also work in ordinary notes and read the note's properties there (`{{this.jira}}`). Switching it on creates the dashboard \"My day\". It also adds the \"Processes\" page (`/processes`): models describe stages, steps, decisions, conditions and sub-workflows; a run guides a feature or a bug through one, with a target branch, the affected repositories and a suggested branch. Checks read GitLab and Jira live, the run keeps only references. Two examples (waterfall, bug fix) are created.",
