  'features.calloutsTitle': 'Callouts',
  'features.calloutsDesc': 'Quotes that start with `> [!type] Title` show as a colored box with an icon, e.g. `note`, `tip`, `warning`, `danger`, `question`, `example` or `quote` (as in Obsidian). With `-` after the type (`> [!note]- Title`) the box starts collapsed, with `+` expanded; the arrow opens and closes it. Insert new boxes with `/callout`. Public links, PDF and Word show them the same way. Without the feature they stay plain quotes.',
