  'features.sum.presentation': 'Present notes as slides and export them as PDF',
  'features.presentationTitle': 'Presentations',
  'features.presentationDesc': 'Shows “Start presentation” in the note menu and “Presentation (PDF)” among the exports. Every `---` after an empty line starts a new slide (without such breaks every `#` and `##` heading does); everything after a line `Note:` is speaker notes. You choose the slide format on the note (frontmatter `presentation: 4:3`, otherwise 16:9). Images, diagrams, tables and embeds look like in the note. Without the feature `---` stays a plain horizontal rule.',
